<script setup>
import ProductImage from "./ProductImage.vue";
import {useCart} from '../composables/cart';import {money} from '../data/catalog';import {useRouter} from 'vue-router';const {open,groups,count,subtotal,delivery,total,change}=useCart();const router=useRouter();function checkout(){open.value=false;router.push('/checkout')}
</script>
<template><v-navigation-drawer v-model="open" location="right" temporary :width="440" style="max-width:100vw"><div class="flex h-full flex-col p-5"><div class="flex items-center justify-between"><h2 class="text-2xl font-black">Your basket ({{count}})</h2><button class="secondary" aria-label="Close basket" @click="open=false"><i class="fa-solid fa-xmark"></i></button></div><div class="flex-1 overflow-y-auto py-5"><div v-if="!count" class="py-16 text-center"><i class="fa-solid fa-basket-shopping text-4xl text-green-700"></i><p class="my-5">Your basket is empty.</p><button class="primary" @click="open=false">Keep shopping</button></div><section v-for="g in groups" :key="g.seller.id" class="mb-5"><h3 class="rounded-xl bg-green-50 p-3 font-bold">{{g.seller.name}}</h3><article v-for="l in g.items" :key="l.key" class="flex items-center gap-3 border-b border-green-100 py-4"><div class="h-16 w-16 shrink-0 overflow-hidden rounded-xl text-2xl"><ProductImage :src="l.image" :alt="l.name" :emoji="l.emoji"/></div><div class="flex-1"><p class="font-bold">{{l.name}}</p><p class="text-xs">{{l.option}}</p><p>{{money(l.price*l.qty)}}</p><button class="text-xs text-red-700" @click="change(l,-l.qty)">Remove</button></div><div class="stepper"><button @click="change(l,-1)" aria-label="Decrease">−</button>{{l.qty}}<button :disabled="l.qty>=l.max" @click="change(l,1)" aria-label="Increase">+</button></div></article></section></div><div v-if="count" class="border-t border-green-100 pt-4"><p class="flex justify-between">Subtotal <b>{{money(subtotal)}}</b></p><p class="my-2 flex justify-between">Estimated delivery <b>{{money(delivery)}}</b></p><p class="my-3 flex justify-between text-xl font-black">Total <span>{{money(total)}}</span></p><button class="primary w-full" @click="checkout">Continue to checkout <i class="fa-solid fa-arrow-right"></i></button></div></div></v-navigation-drawer></template>
